SELECT i.id AS subj_id, i.code AS subj_code, i.name AS subj_name, COALESCE(i.intro, '') AS subj_intro, COALESCE(a.persona, '') AS subj_persona, CASE i.kind WHEN 'language' THEN '语言' ELSE '通用' END AS subj_kind, COALESCE(NULLIF(TRIM(i.levels), ''), 'N5,N4,N3,N2,N1') AS subj_levels, CASE i.visibility WHEN 'public' THEN '公共' ELSE '私有' END AS subj_visibility, CASE i.status WHEN 'active' THEN '启用' WHEN 'disabled' THEN '停用' ELSE '草稿' END AS subj_status, i.owner AS subj_owner, '单人' AS subj_my_role, (SELECT COUNT(*) FROM subject_student s WHERE s.subject_id = i.id AND s.status = 'active') AS subj_student_n, (CASE WHEN i.owner <> '' THEN 1 ELSE 0 END) + (SELECT COUNT(*) FROM subject_teacher t2 WHERE t2.subject_id = i.id AND t2.teacher <> i.owner) AS subj_teacher_n, 1 AS can_manage, CASE WHEN i.status <> 'disabled' THEN 1 ELSE 0 END AS can_assign FROM subject_info i LEFT JOIN subject_ai a ON a.subject_id = i.id ORDER BY i.id
